import{_ as n,W as o,s as l,u as d,ah as c,I as t,w as e,Z as i,A as p}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const C=JSON.parse('{"title":"12 个 ip 命令范例 | LCTT x X-CMD","titleTemplate":false,"description":"12 个 ip 命令范例 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"12 个 ip 命令范例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"12 个 ip 命令范例 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170915 12 ip Command Examples for Linux Users","title":"12 个 ip 命令范例","tag":"201801"},"relativePath":"201801/20170915 12 ip Command Examples for Linux Users.md","filePath":"[post].md"}'),h={name:"201801/20170915 12 ip Command Examples for Linux Users.md"};function r(u,a,g,b,m,v){const s=o("Link");return d(),l("div",null,[a[13]||(a[13]=c(`<h1 id="_12-个-ip-命令范例" tabindex="-1">12 个 ip 命令范例 <a class="header-anchor" href="#_12-个-ip-命令范例" aria-label="Permalink to 12 个 ip 命令范例">​</a></h1><p>一年又一年，我们一直在使用 <code>ifconfig</code> 命令来执行网络相关的任务，比如检查和配置网卡信息。但是 <code>ifconfig</code> 已经不再被维护，并且在最近版本的 Linux 中被废除了！ <code>ifconfig</code> 命令已经被 <code>ip</code> 命令所替代了。</p><p><code>ip</code> 命令跟 <code>ifconfig</code> 命令有些类似，但要强力的多，它有许多新功能。<code>ip</code> 命令完成很多 <code>ifconfig</code> 命令无法完成的任务。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/IP-command-examples-Linux.jpg" alt="IP-command-examples-Linux"></p><p>本教程将会讨论 <code>ip</code> 命令的 12 中最常用法，让我们开始吧。</p><h3 id="案例-1-检查网卡信息" tabindex="-1">案例 1：检查网卡信息 <a class="header-anchor" href="#案例-1-检查网卡信息" aria-label="Permalink to 案例 1：检查网卡信息">​</a></h3><p>检查网卡的诸如 IP 地址，子网等网络信息，使用 <code>ip addr show</code> 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ ip addr show</span></span>
<span class="line"><span></span></span>
<span class="line"><span>或</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[linuxtechi@localhost]$ ip a s</span></span></code></pre></div><p>这会显示系统中所有可用网卡的相关网络信息，不过如果你想查看某块网卡的信息，则命令为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ ip addr show enp0s3</span></span></code></pre></div><p>这里 <code>enp0s3</code> 是网卡的名字。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/IP-addr-show-commant-output.jpg" alt="IP-addr-show-commant-output"></p><h3 id="案例-2-启用-禁用网卡" tabindex="-1">案例 2：启用/禁用网卡 <a class="header-anchor" href="#案例-2-启用-禁用网卡" aria-label="Permalink to 案例 2：启用/禁用网卡">​</a></h3><p>使用 <code>ip</code> 命令来启用一个被禁用的网卡：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip link set enp0s3 up</span></span></code></pre></div><p>而要禁用网卡则使用 <code>down</code> 触发器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip link set enp0s3 down</span></span></code></pre></div><h3 id="案例-3-为网卡分配-ip-地址以及其他网络信息" tabindex="-1">案例 3：为网卡分配 IP 地址以及其他网络信息 <a class="header-anchor" href="#案例-3-为网卡分配-ip-地址以及其他网络信息" aria-label="Permalink to 案例 3：为网卡分配 IP 地址以及其他网络信息">​</a></h3><p>要为网卡分配 IP 地址，我们使用下面命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip addr add 192.168.0.50/255.255.255.0 dev enp0s3</span></span></code></pre></div><p>也可以使用 <code>ip</code> 命令来设置广播地址。默认是没有设置广播地址的，设置广播地址的命令为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ sudo  ip addr add broadcast 192.168.0.255 dev enp0s3</span></span></code></pre></div><p>我们也可以使用下面命令来根据 IP 地址设置标准的广播地址：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$  sudo ip addr add 192.168.0.10/24 brd + dev enp0s3</span></span></code></pre></div><p>如上面例子所示，我们可以使用 <code>brd</code> 代替 <code>broadcast</code> 来设置广播地址。</p><h3 id="案例-4-删除网卡中配置的-ip-地址" tabindex="-1">案例 4：删除网卡中配置的 IP 地址 <a class="header-anchor" href="#案例-4-删除网卡中配置的-ip-地址" aria-label="Permalink to 案例 4：删除网卡中配置的 IP 地址">​</a></h3><p>若想从网卡中删掉某个 IP，使用如下 <code>ip</code> 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip addr del 192.168.0.10/24 dev enp0s3</span></span></code></pre></div><h3 id="案例-5-为网卡添加别名-假设网卡名为-enp0s3" tabindex="-1">案例 5：为网卡添加别名（假设网卡名为 enp0s3） <a class="header-anchor" href="#案例-5-为网卡添加别名-假设网卡名为-enp0s3" aria-label="Permalink to 案例 5：为网卡添加别名（假设网卡名为 enp0s3）">​</a></h3><p>添加别名，即为网卡添加不止一个 IP，执行下面命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$  sudo ip addr add 192.168.0.20/24 dev enp0s3 label enp0s3:1</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/ip-command-add-alias-linux.jpg" alt="ip-command-add-alias-linux"></p><h3 id="案例-6-检查路由-默认网关的信息" tabindex="-1">案例 6：检查路由/默认网关的信息 <a class="header-anchor" href="#案例-6-检查路由-默认网关的信息" aria-label="Permalink to 案例 6：检查路由/默认网关的信息">​</a></h3><p>查看路由信息会给我们显示数据包到达目的地的路由路径。要查看网络路由信息，执行下面命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$  ip route show</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/ip-route-command-output.jpg" alt="ip-route-command-output"></p><p>在上面输出结果中，我们能够看到所有网卡上数据包的路由信息。我们也可以获取特定 IP 的路由信息，方法是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip route get 192.168.0.1</span></span></code></pre></div><h3 id="案例-7-添加静态路由" tabindex="-1">案例 7：添加静态路由 <a class="header-anchor" href="#案例-7-添加静态路由" aria-label="Permalink to 案例 7：添加静态路由">​</a></h3><p>我们也可以使用 IP 来修改数据包的默认路由。方法是使用 <code>ip route</code> 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip route add default via 192.168.0.150/24</span></span></code></pre></div><p>这样所有的网络数据包通过 <code>192.168.0.150</code> 来转发，而不是以前的默认路由了。若要修改某个网卡的默认路由，执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip route add 172.16.32.32 via 192.168.0.150/24 dev enp0s3</span></span></code></pre></div><h3 id="案例-8-删除默认路由" tabindex="-1">案例 8：删除默认路由 <a class="header-anchor" href="#案例-8-删除默认路由" aria-label="Permalink to 案例 8：删除默认路由">​</a></h3><p>要删除之前设置的默认路由，打开终端然后运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$  sudo ip route del 192.168.0.150/24</span></span></code></pre></div><p><strong>注意：</strong> 用上面方法修改的默认路由只是临时有效的，在系统重启后所有的改动都会丢失。要永久修改路由，需要修改或创建 <code>route-enp0s3</code> 文件。将下面这行加入其中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$  sudo vi /etc/sysconfig/network-scripts/route-enp0s3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>172.16.32.32 via 192.168.0.150/24 dev enp0s3</span></span></code></pre></div><p>保存并退出该文件。</p><p>若你使用的是基于 Ubuntu 或 debian 的操作系统，则该要修改的文件为 <code>/etc/network/interfaces</code>，然后添加 <code>ip route add 172.16.32.32 via 192.168.0.150/24 dev enp0s3</code> 这行到文件末尾。</p><h3 id="案例-9-检查所有的-arp-记录" tabindex="-1">案例 9：检查所有的 ARP 记录 <a class="header-anchor" href="#案例-9-检查所有的-arp-记录" aria-label="Permalink to 案例 9：检查所有的 ARP 记录">​</a></h3><p>ARP，是<ruby>地址解析协议<rt>Address Resolution Protocol</rt></ruby>的缩写，用于将 IP 地址转换为物理地址（也就是 MAC 地址）。所有的 IP 和其对应的 MAC 明细都存储在一张表中，这张表叫做 ARP 缓存。</p><p>要查看 ARP 缓存中的记录，即连接到局域网中设备的 MAC 地址，则使用如下 ip 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$  ip neigh</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/ip-neigh-command-linux.jpg" alt="ip-neigh-command-linux"></p><h3 id="案例-10-修改-arp-记录" tabindex="-1">案例 10：修改 ARP 记录 <a class="header-anchor" href="#案例-10-修改-arp-记录" aria-label="Permalink to 案例 10：修改 ARP 记录">​</a></h3><p>删除 ARP 记录的命令为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip neigh del 192.168.0.106 dev enp0s3</span></span></code></pre></div><p>若想往 ARP 缓存中添加新记录，则命令为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ sudo ip neigh add 192.168.0.150 lladdr 33:1g:75:37:r3:84 dev enp0s3 nud perm</span></span></code></pre></div><p>这里 <code>nud</code> 的意思是 “neghbour state”（网络邻居状态），它的值可以是：</p><ul><li><code>perm</code> - 永久有效并且只能被管理员删除</li><li><code>noarp</code> - 记录有效，但在生命周期过期后就允许被删除了</li><li><code>stale</code> - 记录有效，但可能已经过期</li><li><code>reachable</code> - 记录有效，但超时后就失效了</li></ul><h3 id="案例-11-查看网络统计信息" tabindex="-1">案例 11：查看网络统计信息 <a class="header-anchor" href="#案例-11-查看网络统计信息" aria-label="Permalink to 案例 11：查看网络统计信息">​</a></h3><p>通过 <code>ip</code> 命令还能查看网络的统计信息，比如所有网卡上传输的字节数和报文数，错误或丢弃的报文数等。使用 <code>ip -s link</code> 命令来查看：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ ip -s link</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/09/ip-s-command-linux.jpg" alt="ip-s-command-linux"></p><h3 id="案例-12-获取帮助" tabindex="-1">案例 12：获取帮助 <a class="header-anchor" href="#案例-12-获取帮助" aria-label="Permalink to 案例 12：获取帮助">​</a></h3><p>若你想查看某个上面例子中没有的选项，那么你可以查看帮助。事实上对任何命令你都可以寻求帮助。要列出 <code>ip</code> 命令的所有可选项，执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[linuxtechi@localhost]$ ip help</span></span></code></pre></div><p>记住，<code>ip</code> 命令是一个对 Linux 系统管理来说特别重要的命令，学习并掌握它能够让配置网络变得容易。本教程就此结束了，若有任何建议欢迎在下面留言框中留言。</p><hr>`,71)),t("p",null,[a[1]||(a[1]=e("via: ")),i(s,{href:"https://www.linuxtechi.com/ip-command-examples-for-linux-users/"},{default:p(()=>a[0]||(a[0]=[e("https://www.linuxtechi.com/ip-command-examples-for-linux-users/")])),_:1})]),t("p",null,[a[5]||(a[5]=e("作者：")),i(s,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:p(()=>a[2]||(a[2]=[e("Pradeep Kumar")])),_:1}),a[6]||(a[6]=e(" 译者：")),i(s,{href:"https://github.com/lujun9972"},{default:p(()=>a[3]||(a[3]=[e("lujun9972")])),_:1}),a[7]||(a[7]=e(" 校对：")),i(s,{href:"https://github.com/wxy"},{default:p(()=>a[4]||(a[4]=[e("wxy")])),_:1})]),t("p",null,[a[10]||(a[10]=e("本文由 ")),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>a[8]||(a[8]=[e("LCTT")])),_:1}),a[11]||(a[11]=e(" 原创编译，")),i(s,{href:"https://linux.cn/"},{default:p(()=>a[9]||(a[9]=[e("Linux中国")])),_:1}),a[12]||(a[12]=e(" 荣誉推出"))])])}const f=n(h,[["render",r]]);export{C as __pageData,f as default};
